{
  "testCases": [
    {
      "group": "Delegation to overloaded validate method",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mock(ExecutionContext.class)"
            },
            {
              "parameter": "node",
              "value": "ObjectNodeFactory.createObjectNode().put(\"name\", \"value\")"
            }
          ],
          "expected": "The returned Set<ValidationMessage> is exactly the set returned by the overloaded validate(executionContext, node, node, atRoot()) call.",
          "description": "When both ExecutionContext and JsonNode are non‑null, BaseJsonValidator.validate should delegate to the four‑argument overload and return its result."
        },
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "null"
            },
            {
              "parameter": "node",
              "value": "ObjectNodeFactory.createObjectNode()"
            }
          ],
          "expected": "NullPointerException",
          "description": "If the ExecutionContext argument is null, the method should throw a NullPointerException before delegating."
        },
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mock(ExecutionContext.class)"
            },
            {
              "parameter": "node",
              "value": "null"
            }
          ],
          "expected": "NullPointerException",
          "description": "If the JsonNode argument is null, the method should throw a NullPointerException before delegating."
        }
      ]
    },
    {
      "group": "Root path handling",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mock(ExecutionContext.class)"
            },
            {
              "parameter": "node",
              "value": "ObjectNodeFactory.createObjectNode()"
            }
          ],
          "expected": "The atRoot() method is invoked exactly once and its result is passed as the fourth argument to the overloaded validate method.",
          "description": "Ensures that BaseJsonValidator.validate uses the path returned by atRoot() as the instance location for validation."
        }
      ]
    },
    {
      "group": "Integration with subclass implementation",
      "cases": [
        {
          "input": [
            {
              "parameter": "executionContext",
              "value": "mock(ExecutionContext.class)"
            },
            {
              "parameter": "node",
              "value": "ObjectNodeFactory.createObjectNode().put(\"age\", 30)"
            }
          ],
          "expected": "A non‑empty Set<ValidationMessage> containing messages produced by the concrete subclass’s four‑argument validate implementation.",
          "description": "When a concrete subclass (e.g., MinimumValidator) overrides the four‑argument validate, the single‑argument validate should return the messages generated by that subclass."
        }
      ]
    }
  ]
}
